#include <string>
#include <vector>

using namespace std;

class Solution {
public:
    int dp[301][27][27];

    int dist(int a, int b) {
        if (a == 26 || b == 26) return 0;
        return abs(a / 6 - b / 6) + abs(a % 6 - b % 6);
    }

    int minimumDistance(string word) {
        int n = word.size();
        for (int i = n; i >= 0; --i)
            for (int f1 = 0; f1 < 27; ++f1)
                for (int f2 = 0; f2 < 27; ++f2)
                    dp[i][f1][f2] = 0;

        for (int i = n - 1; i >= 0; --i) {
            int cur = word[i] - 'A';
            for (int f1 = 0; f1 < 27; ++f1)
                for (int f2 = 0; f2 < 27; ++f2)
                    dp[i][f1][f2] = min(
                        dist(f1, cur) + dp[i + 1][cur][f2],
                        dist(f2, cur) + dp[i + 1][f1][cur]
                    );
        }
        return dp[0][26][26];
    }
};
